<section class="section" id="lugares"><div class="sectionhead"><div><p class="eyebrow"><?=e($t['connect'])?></p><h2><?=e($t['directory_heading'])?> <?=e($name)?></h2></div><p><?=e($t['directory_intro'])?></p></div><p class="directory-map"><a class="text-link" href="<?=e($map)?>" target="_blank" rel="noopener noreferrer"><?=e($t['map'])?></a></p><div id="catalogo-local" data-destino="<?=e($slug)?>"><div class="directory-tabs" role="tablist" aria-label="<?=e($t['directory'])?>"><button type="button" role="tab" id="directory-tab-todos" aria-selected="true" aria-controls="directory-panel" tabindex="0"><?=e($t['all'])?></button><?php foreach($d['categories'] as $category):?><button type="button" role="tab" id="directory-tab-<?=e($category['code'])?>" aria-selected="false" aria-controls="directory-panel" tabindex="-1" data-category="<?=e($category['code'])?>"><?=e($category['label'])?></button><?php endforeach;?></div><div id="directory-panel" role="tabpanel" aria-labelledby="directory-tab-todos" tabindex="0"><?php if(!$d['businesses']):?><p class="directory-empty"><?=e($t['empty'])?></p><?php else:?><div class="directory-grid"><?php foreach($d['businesses'] as $business):$features=$business['features']??[];$hasPage=isset($features['business_page']);$isFeatured=isset($features['highlighted_card']);$hasDetails=isset($features['extended_description']);$hasLogo=isset($features['business_logo']);$pageUrl=u('/'.$localePrefix.'negocios/'.$business['public_id'].'/');?><article class="directory-card directory-card-tier-<?=e($business['plan_code'])?><?=$isFeatured?' is-featured':''?>" data-category="<?=e($business['code'])?>" id="negocio-<?=e($business['public_id'])?>"><?php if($isFeatured):?><span class="directory-featured-badge"><?=e($business['plan_code']==='page_premium'?$t['premium']:$t['featured'])?></span><?php endif;?><div class="directory-card-body"><?php if($hasLogo):?><div class="directory-business-mark"><?php if($business['image_path']):?><img src="<?=e(mediaPath(['path'=>$business['image_path']]))?>" alt="" width="<?=e($business['width']?:160)?>" height="<?=e($business['height']?:160)?>" loading="lazy" decoding="async"><?php else:?><span aria-hidden="true"><?=e(businessInitials($business['display_name']))?></span><?php endif;?></div><?php endif;?><p class="eyebrow"><?=e($business['label'])?></p><h3><?php if($hasPage):?><a href="<?=e($pageUrl)?>"><?=e($business['display_name'])?></a><?php else:?><?=e($business['display_name'])?><?php endif;?></h3><?php if($business['plan_code']!=='free'&&(trim((string)$business['address_text'])!==''||$business['latitude']!==null)):$businessMap=trim((string)($business['location_map_url']??''))?:($business['latitude']!==null&&$business['longitude']!==null?'https://www.google.com/maps/search/?api=1&query='.rawurlencode($business['latitude'].','.$business['longitude']):'https://www.google.com/maps/search/?api=1&query='.rawurlencode($business['address_text'].' '.$business['location_reference']));?><a class="text-link directory-location-link" href="<?=e($businessMap)?>" target="_blank" rel="noopener noreferrer"><?=e(trim((string)$business['address_text'])!==''?$business['address_text']:$t['map'])?> ↗</a><?php endif;?><?php if($business['plan_code']!=='free'&&$business['summary']!==''):?><p class="directory-description"><?=e($business['summary'])?></p><?php endif;?><?php if($business['plan_code']!=='free'):?><p><small><?=e($business['information_status']==='VERIFICADO'?$t['verified']:$t['public_data'])?></small></p><?php endif;?><?php if($hasDetails):?><details class="directory-card-details"><summary><?=e($t['more_info'])?></summary><p><?=nl2br(e($business['description']))?></p><?php if(isset($features['direct_contact'])):foreach($d['public_contacts'][(int)$business['id']]??[] as $contact):$href=contactHref($contact);if($href):?><a class="text-link" href="<?=e($href)?>"<?=str_starts_with($href,'http')?' target="_blank" rel="noopener noreferrer"':''?>><?=e($t['contact_business'])?></a><?php break;endif;endforeach;endif;?></details><?php elseif(isset($features['direct_contact'])):foreach($d['public_contacts'][(int)$business['id']]??[] as $contact):$href=contactHref($contact);if($href):?><a class="text-link" href="<?=e($href)?>"<?=str_starts_with($href,'http')?' target="_blank" rel="noopener noreferrer"':''?>><?=e($t['contact_business'])?></a><?php break;endif;endforeach;endif;?><?php if($hasPage):?><a class="text-link directory-business-page-link" href="<?=e($pageUrl)?>"><?=e($t['business_page'])?> →</a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></div></div></section>
<section class="destination-practical"><details><summary><?=e($t['practical'])?></summary><p><?=e($t['practical_text'])?></p><a class="text-link" href="<?=e($map)?>" target="_blank" rel="noopener noreferrer"><?=e($t['map'])?></a></details><details id="eventos"><summary><?=e($t['events_heading'])?> <?=e($name)?></summary><p><?=e($t['no_events'])?></p><a class="text-link" href="<?=e($interest)?>"><?=e($t['organize'])?></a></details></section>
