<script>(()=>{const root=document.getElementById('catalogo-local');if(!root)return;const tabs=[...root.querySelectorAll('[role="tab"]')],cards=[...root.querySelectorAll('.directory-card')];function select(tab,focus=false){const category=tab.dataset.category||'';for(const item of tabs){const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1;if(active){document.getElementById('directory-panel').setAttribute('aria-labelledby',item.id);if(focus)item.focus();}}for(const card of cards)card.hidden=!!category&&card.dataset.category!==category;}for(const tab of tabs){tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',event=>{const i=tabs.indexOf(tab);let n;if(event.key==='ArrowRight')n=(i+1)%tabs.length;if(event.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;if(event.key==='Home')n=0;if(event.key==='End')n=tabs.length-1;if(n!==undefined){event.preventDefault();select(tabs[n],true);}});}})();</script><script>(()=>{const grid=document.getElementById('atractivos-destino');const button=document.getElementById('cargar-mas-atractivos');if(!grid||!button)return;const cards=[...grid.querySelectorAll('article')];const rowSize=()=>Math.max(1,getComputedStyle(grid).gridTemplateColumns.split(' ').length);let visible=Math.min(rowSize(),cards.length);const update=()=>{cards.forEach((card,index)=>card.hidden=index>=visible);button.hidden=visible>=cards.length;};update();button.addEventListener('click',()=>{visible=Math.min(cards.length,visible+rowSize());update();});})();</script>
